#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include "gi_bypass.h"
#include "gi_raw_cs.h" // generated by build.bat: g_gi_raw_s<scale>_a<ao> for scale 0..3, ao 0..3

#include <atomic>
#include <cstring>
#include <mutex>
#include <set>
#include <unordered_map>

void logf(const char *fmt, ...);

namespace gi
{
	// identity_hash() values (DXIL part only). Whole-container hashes were ea12dd2b624b6962 / 6e9ffce615b836da
	// with ReShade and c6a0de20147d5356 / 6f7dded184364b6f without it - same programs, different debug names.
	static constexpr uint64_t k_hash_temporal = 0x2065ab87ddffd305ull;
	static constexpr uint64_t k_hash_spatial  = 0x0f647000c451f382ull;

	uint64_t identity_hash(const void *code, size_t size)
	{
		const uint8_t *data = static_cast<const uint8_t *>(code);
		const uint8_t *hashed = data; size_t len = size;
		if (size >= 32 && memcmp(data, "DXBC", 4) == 0)
		{
			uint32_t parts = 0; memcpy(&parts, data + 28, 4);
			for (uint32_t i = 0; i < parts && 32 + 4 * (i + 1) <= size; ++i)
			{
				uint32_t off = 0, part_size = 0; memcpy(&off, data + 32 + 4 * i, 4);
				if (off + 8 > size) break;
				memcpy(&part_size, data + off + 4, 4);
				if (memcmp(data + off, "DXIL", 4) == 0 && off + 8 + part_size <= size) { hashed = data + off + 8; len = part_size; break; }
			}
		}
		uint64_t h = 1469598103934665603ull;
		for (size_t i = 0; i < len; ++i) { h ^= hashed[i]; h *= 1099511628211ull; }
		return h;
	}

	static const char *const k_scale_names[] = { "x1", "xPI", "x2", "x0.5" };
	static const char *const k_ao_names[] = { "off", "soft 0.25m", "soft 1m", "hard 1.5m" };
	static constexpr int k_variant_count = 4; // scales
	static constexpr int k_ao_count = 4;
	struct Code { const void *code; size_t size; };
#define GI_V(s, a) { g_gi_raw_s##s##_a##a, sizeof(g_gi_raw_s##s##_a##a) }
	static const Code k_code[4][4] = {
		{ GI_V(0, 0), GI_V(0, 1), GI_V(0, 2), GI_V(0, 3) },
		{ GI_V(1, 0), GI_V(1, 1), GI_V(1, 2), GI_V(1, 3) },
		{ GI_V(2, 0), GI_V(2, 1), GI_V(2, 2), GI_V(2, 3) },
		{ GI_V(3, 0), GI_V(3, 1), GI_V(3, 2), GI_V(3, 3) },
	};
#undef GI_V

	static std::atomic<bool> s_enabled{false};
	static std::atomic<int> s_scale{0};
	static std::atomic<int> s_ao{2};
	static std::atomic<bool> s_allowed{true};

	static std::mutex s_mtx;
	static std::set<uint64_t> s_temporal_pipes, s_spatial_pipes;
	static ID3D12PipelineState *s_pso[k_variant_count][k_ao_count] = {};
	static ID3D12RootSignature *s_pso_rootsig = nullptr;

	struct ListState { int kind = 0; int spatial_count = 0; };
	static std::unordered_map<uint64_t, ListState> s_lists;

	bool enabled() { return s_enabled.load(); }
	void set_enabled(bool on) { s_enabled = on; }
	void set_allowed(bool allowed) { s_allowed = allowed; }
	void set_scale(int index) { if (index >= 0 && index < k_variant_count) s_scale = index; }
	void set_ao(int index) { if (index >= 0 && index < k_ao_count) s_ao = index; }
	void next_ao()
	{
		const int a = (s_ao.load() + 1) % k_ao_count;
		s_ao = a;
		logf("GI bypass AO: %s", k_ao_names[a]);
	}
	void toggle()
	{
		const bool on = !s_enabled.load();
		s_enabled = on;
		std::lock_guard lock(s_mtx);
		logf("GI bypass: %s (scale %s, AO %s, temporal pipes %zu, spatial pipes %zu, replacement %s)", on ? "ON" : "OFF",
			k_scale_names[s_scale.load()], k_ao_names[s_ao.load()], s_temporal_pipes.size(), s_spatial_pipes.size(), s_pso[0][0] ? "ready" : "NOT created");
	}
	void next_scale()
	{
		const int s = (s_scale.load() + 1) % k_variant_count;
		s_scale = s;
		logf("GI bypass scale: %s", k_scale_names[s]);
	}

	static void create_variants(ID3D12Device *device, ID3D12RootSignature *rs)
	{
		if (s_pso_rootsig == rs && s_pso[0][0]) return;
		for (auto &row : s_pso) for (auto &p : row) { if (p) p->Release(); p = nullptr; }
		s_pso_rootsig = rs;
		for (int s = 0; s < k_variant_count; ++s)
			for (int a = 0; a < k_ao_count; ++a)
			{
				D3D12_COMPUTE_PIPELINE_STATE_DESC d = {};
				d.pRootSignature = rs;
				d.CS = { k_code[s][a].code, k_code[s][a].size };
				const HRESULT hr = device->CreateComputePipelineState(&d, IID_PPV_ARGS(&s_pso[s][a]));
				if (FAILED(hr))
				{
					logf("GI bypass: creating replacement pipeline %s/%s with the game's root signature failed 0x%08lx", k_scale_names[s], k_ao_names[a], hr);
					s_pso[s][a] = nullptr;
				}
			}
		if (s_pso[0][0]) logf("GI bypass: replacement pipelines created (root signature %p)", rs);
	}

	void on_pipeline(ID3D12Device *device, ID3D12RootSignature *rs, uint64_t hash, uint64_t pipeline)
	{
		if (hash != k_hash_temporal && hash != k_hash_spatial) return;
		std::lock_guard lock(s_mtx);
		if (hash == k_hash_temporal) s_temporal_pipes.insert(pipeline);
		else
		{
			s_spatial_pipes.insert(pipeline);
			if (device && rs) create_variants(device, rs);
		}
	}

	void on_destroy_pipeline(uint64_t pipeline)
	{
		std::lock_guard lock(s_mtx);
		s_temporal_pipes.erase(pipeline);
		s_spatial_pipes.erase(pipeline);
	}

	void on_bind_compute(uint64_t list, uint64_t pipeline)
	{
		std::lock_guard lock(s_mtx);
		const int kind = s_temporal_pipes.count(pipeline) ? 1 : s_spatial_pipes.count(pipeline) ? 2 : 0;
		if (kind == 0)
		{
			auto it = s_lists.find(list);
			if (it != s_lists.end()) it->second.kind = 0;
			return;
		}
		s_lists[list].kind = kind;
	}

	void on_reset(uint64_t list)
	{
		std::lock_guard lock(s_mtx);
		s_lists.erase(list);
	}

	bool on_dispatch(uint64_t list, ID3D12PipelineState **swap_to)
	{
		if (swap_to) *swap_to = nullptr;
		if (!s_enabled.load() || !s_allowed.load() || !swap_to) return false;
		std::lock_guard lock(s_mtx);
		auto it = s_lists.find(list);
		if (it == s_lists.end() || it->second.kind == 0) return false;
		ListState &st = it->second;
		ID3D12PipelineState *pso = s_pso[s_scale.load()][s_ao.load()];
		if (!pso) return false; // replacement unavailable: leave the game's denoiser alone

		if (st.kind == 1) // temporal pass: start of the chain
		{
			st.spatial_count = 0;
			return true; // skip
		}
		// spatial pass
		++st.spatial_count;
		if (st.spatial_count == 1)
			return true; // skip pass #1 (it would overwrite the raw signal)
		if (st.spatial_count == 2)
		{
			*swap_to = pso; // pass #2 runs our shader with the game's bindings (caller binds it, outside our lock)
			static bool logged = false;
			if (!logged) { logged = true; logf("GI bypass: first replacement dispatch recorded"); }
		}
		return false;
	}
}
